result = subprocess.run([sys.executable, "-u", "-m", "experiments.exp_139_mask2former.tests.test_equivalence",
                         "--suite", "gpu", "--annotations", str(annotations), "--images", str(images),
                         "--output", str(output), "--skip-loader"], cwd=root, env=env)
